def extend(terms, clauses, clause, condition, rule):
    """Add twenty-six distinct operational schedules."""
    # Missing optional main headings still have a place in the extended agreement.
    titles = ('Parties and definitions', 'Collaboration and administration', 'Access, use and sharing',
              'Information protection', 'Deletion and incident notification', 'Controlled platform access',
              'Processing records and audit access', 'Background materials and work scope',
              'Publication notice, objections and delay', 'Delivery, responsible use and project close-out',
              'Ownership and general arrangements')
    present = {c['clause_id'] for c in clauses}
    for i, title in enumerate(titles, 1):
        if str(i) not in present:
            clause(str(i), title)
    for number, (title, asset, fields, activity, overview, operation, action, field, value, days) in enumerate(SCHEDULES, 12):
        # Expected literal scope/clock values name the same parties as the PDF;
        # no evaluator-only role names are hidden inside these free-text values.
        activity = activity.replace('Provider', terms['provider']).replace('Recipient', terms['recipient'])
        clause(str(number), title)
        clause(f'{number}.1', f'{asset} means the project information resource containing {fields}. It concerns {activity}.', relevant=True)
        clause(f'{number}.2', overview, relevant=True)
        clause(f'{number}.3', operation, relevant=True)
        clause(f'{number}.4', f'Recipient must maintain complete {asset} for {activity}.',
               rule('obligation', 'maintain', asset, conditions=[condition('completeness', 'complete'), condition('scope', activity)]))
        clause(f'{number}.5', f'Recipient must make the {asset} described in clause {number}.4 available to Provider upon request.',
               rule('obligation', 'provideAccess', asset, conditions=[condition('recipient', 'Provider'), condition('event', 'request'), condition('scope', activity)]))
        permission = action == 'read'
        clause(f'{number}.6', f'Recipient {"may" if permission else "must not"} {action} {asset} '
               + (f'for {value}.' if field == 'purpose' else f'to {value}.' if field == 'recipient'
                  else f'in {value}.' if field == 'spatial' else f'using {value}.'),
               rule('permission' if permission else 'prohibition', action, asset, conditions=[condition(field, value)]))
        clause(f'{number}.7', f'Recipient must share {asset} with Provider within {days} days after Provider requests {asset}.',
               rule('obligation', 'share', asset, conditions=[condition('recipient', 'Provider'),
                   condition('elapsedTime', f'P{days}D', 'lteq'), condition('event', f"{terms['provider']} requests {asset}")]))
        clause(f'{number}.8', 'The project steering group discusses the operational arrangements for this schedule at its regular meetings. '
               'Meeting dates, agendas, funding allocations and contact substitutions are administrative matters. '
               'They are recorded separately from the information-handling rules and from the signed agreement text.')
    clauses.sort(key=lambda c: tuple(int(n) for n in c['clause_id'].split('.')))
